<script>document.addEventListener('DOMContentLoaded',()=>{const f=document.querySelector('[data-leave-form]'),l=f?.querySelector('[data-date-list]');if(!f||!l)return;const r=()=>{[...l.querySelectorAll('[data-date-row]')].forEach((x,i)=>{x.querySelector('.workspace-leave-date-index').textContent=i+1;x.querySelector('[data-remove-leave-date]').disabled=l.children.length===1;});};f.querySelector('[data-add-leave-date]').addEventListener('click',()=>{const x=l.querySelector('[data-date-row]').cloneNode(true);x.querySelector('input').value='';l.append(x);r();});l.addEventListener('click',e=>{if(e.target.matches('[data-remove-leave-date]')&&l.children.length>1){e.target.closest('[data-date-row]').remove();r();}});r();});</script>
